1	import { readFile } from 'node:fs/promises';
2	import * as path from 'pathe';
3	import { assertSyntheticEvidence } from '../policy/payment-signals.ts';
4	import { receiptDigest, sha256 } from './canonicalize.ts';
5	import { parseMigrationReceipt } from './schema.ts';
6	import {
7		WITNESS_ANGULAR_REALWORLD_SCHEMA,
8		verifyWitnessAngularRealworldEvidence,
9	} from './witness-angular-realworld.ts';
10	import {
11		WITNESS_REACT_BOILERPLATE_SCHEMA,
12		verifyWitnessReactBoilerplateEvidence,
13	} from './witness-react-boilerplate.ts';
14	import {
15		WITNESS_NEXT_KILLED_BY_GOOGLE_SCHEMA,
16		verifyWitnessNextKilledByGoogleEvidence,
17	} from './witness-next-killedbygoogle.ts';
18	import {
19		REACT_AVATAAARS_COMPATIBILITY_SCHEMA,
20		verifyReactAvataaarsCompatibilityEvidence,
21	} from './react-avataaars-compatibility.ts';
22	import { REACT_CALCULATOR_SCHEMA, verifyReactCalculatorEvidence } from './react-calculator.ts';
23	import { REACT_GRAPHIQL_013_SCHEMA, verifyReactGraphiQL013Evidence } from './react-graphiql-013.ts';
24	import {
25		REACT_ACTUAL_BUDGET_SCHEMA,
26		verifyReactActualBudgetEvidence,
27	} from './react-actual-budget-v22-12-9.ts';
28	
29	function markdownPath(jsonPath: string): string {
30		return jsonPath.endsWith('.json')
31			? `${jsonPath.slice(0, -'.json'.length)}.md`
32			: `${jsonPath}.md`;
33	}
34	
35	export type ReceiptPathBase = 'repository' | 'versionless';
36	
37	export interface VerifyReceiptOptions {
38		repositoryRoot?: string;
39		receiptPathBase?: ReceiptPathBase;
40		artifactPathBase?: ReceiptPathBase;
41		requireAggregate?: boolean;
42	}
43	
44	export function resolveReceiptPath(
45		value: string,
46		repositoryRoot: string,
47		base: ReceiptPathBase,
48	): string {
49		if (path.isAbsolute(value)) return path.normalize(value);
50		const explicitBase =
51			base === 'repository'
52				? path.normalize(repositoryRoot)
53				: path.join(path.normalize(repositoryRoot), '.versionless');
54		return path.resolve(explicitBase, value);
55	}
56	
57	export async function verifyReceipt(
58		file: string,
59		options: VerifyReceiptOptions = {},
60	): Promise<{ valid: true; digest: string; artifacts: number }> {
61		const explicitRoot = options.repositoryRoot
62			? path.normalize(options.repositoryRoot)
63			: undefined;
64		const absolute = explicitRoot
65			? resolveReceiptPath(file, explicitRoot, options.receiptPathBase ?? 'repository')
66			: path.resolve(file);
67		const raw = JSON.parse(await readFile(absolute, 'utf8')) as { schemaVersion?: unknown };
68		if (raw.schemaVersion === WITNESS_ANGULAR_REALWORLD_SCHEMA) {
69			const root = explicitRoot ?? path.resolve(path.dirname(absolute), '../../..');
70			const verified = await verifyWitnessAngularRealworldEvidence(root);
71			return { valid: true, digest: verified.digest, artifacts: verified.artifacts };
72		}
73		if (raw.schemaVersion === WITNESS_REACT_BOILERPLATE_SCHEMA) {
74			const root = explicitRoot ?? path.resolve(path.dirname(absolute), '../../..');
75			const verified = await verifyWitnessReactBoilerplateEvidence(root);
76			return { valid: true, digest: verified.digest, artifacts: verified.artifacts };
77		}
78		if (raw.schemaVersion === WITNESS_NEXT_KILLED_BY_GOOGLE_SCHEMA) {
79			const root = explicitRoot ?? path.resolve(path.dirname(absolute), '../../..');
80			const verified = await verifyWitnessNextKilledByGoogleEvidence(root);
81			return { valid: true, digest: verified.digest, artifacts: verified.artifacts };
82		}
83		if (raw.schemaVersion === REACT_AVATAAARS_COMPATIBILITY_SCHEMA) {
84			const root = explicitRoot ?? path.resolve(path.dirname(absolute), '../../../..');
85			const verified = await verifyReactAvataaarsCompatibilityEvidence(root);
86			return { valid: true, digest: verified.digest, artifacts: verified.artifacts };
87		}
88		if (raw.schemaVersion === REACT_CALCULATOR_SCHEMA) {
89			const root = explicitRoot ?? path.resolve(path.dirname(absolute), '../../..');
90			const verified = await verifyReactCalculatorEvidence(root);
91			return { valid: true, digest: verified.digest, artifacts: 5 };
92		}
93		if (raw.schemaVersion === REACT_GRAPHIQL_013_SCHEMA) {
94			const root = explicitRoot ?? path.resolve(path.dirname(absolute), '../../..');
95			const verified = await verifyReactGraphiQL013Evidence(root);
96			return { valid: true, digest: verified.digest, artifacts: verified.artifacts };
97		}
98		if (raw.schemaVersion === REACT_ACTUAL_BUDGET_SCHEMA) {
99			const root = explicitRoot ?? path.resolve(path.dirname(absolute), '../../..');
100			const verified = await verifyReactActualBudgetEvidence(root);
101			return { valid: true, digest: verified.digest, artifacts: verified.artifacts };
102		}
103		const receipt = parseMigrationReceipt(raw);
104		assertSyntheticEvidence(receipt);
105		const calculated = receiptDigest(receipt);
106		if (calculated !== receipt.integrity.canonicalDigest)
107			throw new Error(`Canonical digest mismatch: ${calculated}`);
108		const root = explicitRoot ?? path.resolve(path.dirname(absolute), '../../..');
109		for (const artifact of receipt.artifacts) {
110			const artifactFile = explicitRoot
111				? resolveReceiptPath(
112						artifact.path,
113						explicitRoot,
114						options.artifactPathBase ?? 'repository',
115					)
116				: path.join(root, artifact.path);
117			const actual = sha256(await readFile(artifactFile));
118			if (actual !== artifact.sha256)
119				throw new Error(`Artifact digest mismatch: ${artifact.path}`);
120		}
121		const report = await readFile(markdownPath(absolute), 'utf8');
122		if (!report.includes(receipt.integrity.canonicalDigest))
123			throw new Error('Derived Markdown is not linked to canonical digest');
124		if (options.requireAggregate ?? true) {
125			const aggregate = JSON.parse(
126				await readFile(path.join(root, 'evidence/runs/aggregate.json'), 'utf8'),
127			) as {
128				fixtures?: Array<{ receipt?: string; digest?: string }>;
129			};
130			const receiptRelative = path.relative(root, absolute);
131			if (
132				!aggregate.fixtures?.some(
133					(item) =>
134						item.receipt === receiptRelative &&
135						item.digest === receipt.integrity.canonicalDigest,
136				)
137			)
138				throw new Error('Aggregate is not linked to the canonical receipt');
139		}
140		return { valid: true, digest: calculated, artifacts: receipt.artifacts.length };
141	}
