	| 'ordinary'
	| 'cyclonedx-components'
	| 'cyclonedx-component'
	| 'cyclonedx-hashes'
	| 'cyclonedx-hash'
	| 'runtime-verticals'
	| 'runtime-vertical'
	| 'runtime-lanes'
	| 'runtime-lane'
	| 'runtime-runs'

