1	import { readFile } from 'node:fs/promises';
2	import * as path from 'pathe';
3	import { describe, expect, it } from 'vitest';
4	import {
5		parseWitnessReactHospitalrunReceipt,
6		REACT_HOSPITALRUN_CANONICAL_DIGEST,
7		REACT_HOSPITALRUN_RECEIPT_PATH,
8		renderWitnessReactHospitalrunReceipt,
9		verifyWitnessReactHospitalrunEvidence,
10		WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS,
11		WITNESS_REACT_HOSPITALRUN_FAILED_REQUESTS,
12		WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH,
13		WITNESS_REACT_HOSPITALRUN_REGISTRATION_ATTEMPTS,
14		WITNESS_REACT_HOSPITALRUN_ROUTES,
15		WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_REQUESTS,
16		witnessReactHospitalrunBehaviorDigest,
17		witnessReactHospitalrunDigest,
18		witnessReactHospitalrunRawDigest,
19		type WitnessReactHospitalrunReceipt,
20	} from '../src/receipts/witness-react-hospitalrun.ts';
21	
22	const root = path.resolve(import.meta.dirname, '../../..');
23	
24	async function published(): Promise<WitnessReactHospitalrunReceipt> {
25		return parseWitnessReactHospitalrunReceipt(
26			JSON.parse(
27				await readFile(path.join(root, WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH), 'utf8'),
28			) as unknown,
29		);
30	}
31	
32	function resealed(receipt: WitnessReactHospitalrunReceipt): WitnessReactHospitalrunReceipt {
33		const copy = structuredClone(receipt);
34		copy.integrity.canonicalDigest = witnessReactHospitalrunDigest(copy);
35		return copy;
36	}
37	
38	/**
39	 * Reseals a tampered receipt as thoroughly as a forger could: every per-run
40	 * digest is recomputed over the edited content before the receipt digest is
41	 * sealed. The digests therefore cannot be what rejects the edit, which is the
42	 * point — each test below has to be caught by the specific evidence check it
43	 * targets rather than by a hash that happened to stop it first.
44	 */
45	function resealedDeep(receipt: WitnessReactHospitalrunReceipt): WitnessReactHospitalrunReceipt {
46		const copy = structuredClone(receipt);
47		for (const run of copy.runs) {
48			run.semanticDigest = witnessReactHospitalrunRawDigest(run);
49			run.behaviorDigest = witnessReactHospitalrunBehaviorDigest(run);
50		}
51		copy.integrity.canonicalDigest = witnessReactHospitalrunDigest(copy);
52		return copy;
53	}
54	
55	describe('HospitalRun direct Witness receipt', () => {
56		it('verifies the published browser proof and its rendered companion', async () => {
57			const verified = await verifyWitnessReactHospitalrunEvidence(root);
58			expect(verified.valid).toBe(true);
59			expect(verified.receipt.result).toBe('pass');
60			expect(verified.receipt.runs).toHaveLength(4);
61			expect(verified.receipt.canonicalReceipt.path).toBe(REACT_HOSPITALRUN_RECEIPT_PATH);
62			expect(verified.receipt.canonicalReceipt.canonicalDigest).toBe(
63				REACT_HOSPITALRUN_CANONICAL_DIGEST,
64			);
65			expect(
66				await readFile(
67					path.join(root, path.dirname(WITNESS_REACT_HOSPITALRUN_RECEIPT_PATH), 'receipt.md'),
68					'utf8',
69				),
70			).toBe(renderWitnessReactHospitalrunReceipt(verified.receipt));
71		});
72	
73		it('proves one behavior across both lanes and both passes', async () => {
74			const receipt = await published();
75			const digests = new Set(receipt.runs.map((run) => run.behaviorDigest));
76			expect(digests.size).toBe(1);
77			expect([...digests]).toEqual([receipt.mutation.restoredBehaviorDigest]);
78			expect(receipt.runs.map((run) => `${run.lane}:${run.pass}`).sort()).toEqual([
79				'baseline:1',
80				'baseline:2',
81				'migrated:1',
82				'migrated:2',
83			]);
84			for (const run of receipt.runs)
85				expect(witnessReactHospitalrunBehaviorDigest(run)).toBe(run.behaviorDigest);
86		});
87	
88		it('drives the whole clinical journey rather than a page load', async () => {
89			const receipt = await published();
90			for (const run of receipt.runs) {
91				expect(run.routes).toEqual([...WITNESS_REACT_HOSPITALRUN_ROUTES]);
92				const kinds = run.interactions.map((interaction) => interaction.kind);
93				expect(kinds).toContain('type');
94				expect(kinds).toContain('hover');
95				expect(kinds).toContain('scroll');
96				expect(kinds.filter((kind) => kind === 'click').length).toBeGreaterThanOrEqual(10);
97			}
98			expect(receipt.persistence).toEqual({
99				store: 'browser-local-pouchdb',
100				stubbed: false,
101				survivesOnlineReload: true,
102			});
103		});
104	
105		it('claims scroll only where the document genuinely overflows the viewport', async () => {
106			const receipt = await published();
107			expect(receipt.scrollSurface.state).toBe('measured-genuine-viewport-scroll');
108			expect(receipt.scrollSurface.route).toBe('/appointments');
109			expect(receipt.scrollSurface.viewport).toEqual({ width: 1280, height: 720 });
110			expect(receipt.scrollSurface.clientHeight).toBe(720);
111			expect(receipt.scrollSurface.scrollHeight).toBeGreaterThan(
112				receipt.scrollSurface.clientHeight,
113			);
114			expect(receipt.nonclaims.join('\n')).toContain('Scroll is claimed only for');
115		});
116	
117		it('accounts for every console error exactly instead of allowing them', async () => {
118			const receipt = await published();
119			expect(receipt.consoleErrors).toEqual(WITNESS_REACT_HOSPITALRUN_CONSOLE_ERRORS);
120			for (const run of receipt.runs) {
121				expect(run.consoleErrorInventory.policy).toBe(
122					'exact-app-scoped-expected-console-errors',
123				);
124				expect(run.consoleErrorInventory.outsideInventory).toEqual([]);
125				expect(run.consoleErrorInventory.observed).toEqual(run.consoleErrorInventory.expected);
126				expect(run.witnessRecord.consoleErrors).toBe(run.consoleErrorInventory.total);
127			}
128			const baseline = receipt.runs.find((run) => run.lane === 'baseline');
129			const migrated = receipt.runs.find((run) => run.lane === 'migrated');
130			expect(baseline?.consoleErrorInventory.observed[0]?.message).toContain(
131				'Error during service worker registration',
132			);
133			expect(migrated?.consoleErrorInventory.observed[0]?.message).toContain('404 (Not Found)');
134		});
135	
136		it('accounts for every failed request exactly instead of allowing them', async () => {
137			const receipt = await published();
138			expect(receipt.failedRequests).toEqual(WITNESS_REACT_HOSPITALRUN_FAILED_REQUESTS);
139			for (const run of receipt.runs) {
140				expect(run.failedRequestInventory.policy).toBe(
141					'exact-app-scoped-expected-failed-requests',
142				);
143				expect(run.failedRequestInventory.outsideInventory).toEqual([]);
144				expect(run.witnessRecord.failedRequests).toBe(run.failedRequestInventory.total);
145				expect(run.failedRequestInventory.observed).toEqual([
146					{ method: 'GET', path: '/service-worker.js', reason: 'net::ERR_ABORTED', count: 2 },
147				]);
148			}
149		});
150	
151		it('records the refused registration and the baseline/target worker difference', async () => {
152			const receipt = await published();
153			expect(receipt.serviceWorkerDifference.masked).toBe(false);
154			for (const run of receipt.runs) {
155				expect(run.blockedServiceWorkerRuntime.registration).toBe(
156					'application-register-refused-by-context',
157				);
158				expect(run.blockedServiceWorkerRuntime.workerEvents).toEqual([]);
159				expect(
160					run.blockedServiceWorkerRuntime.requests.filter(
161						(event) => event.source === 'browser' && event.phase === 'request',
162					),
163				).toHaveLength(WITNESS_REACT_HOSPITALRUN_REGISTRATION_ATTEMPTS);
164				expect(run.blockedServiceWorkerRuntime.requestTally).toEqual(
165					expect.arrayContaining([...WITNESS_REACT_HOSPITALRUN_SERVICE_WORKER_REQUESTS[run.lane]]),
166				);
167				for (const checkpoint of run.blockedServiceWorkerRuntime.checkpoints) {
168					expect(checkpoint.registrations).toBe(0);
169					expect(checkpoint.controller).toBeNull();
170					expect(checkpoint.cacheNames).toEqual([]);
171					expect(checkpoint.workerEvents).toEqual([]);
172				}
173			}
174			const baseline = receipt.runs.filter((run) => run.lane === 'baseline');
175			const migrated = receipt.runs.filter((run) => run.lane === 'migrated');
176			expect(
177				baseline.map((run) =>
178					run.blockedServiceWorkerRuntime.emittedOutputFiles.map((file) => file.path),
179				),
180			).toEqual([['service-worker.js'], ['service-worker.js']]);
181			expect(migrated.map((run) => run.blockedServiceWorkerRuntime.emittedOutputFiles)).toEqual([
182				[],
183				[],
184			]);
185		});
186	
187		it('states plainly that neither lane has a silent console', async () => {
188			const receipt = await published();
189			expect(receipt.nonclaims.join('\n')).toContain('Neither lane has a silent console');
190			expect(receipt.nonclaims.join('\n')).toContain('not counted');
191		});
192	
193		it('rejects a console error smuggled in outside the pinned inventory', async () => {
